package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/gofiber/fiber/v2"
)

// webhookRequest represents the expected JSON request body
type webhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// webhookTestPayload is the payload sent to test the webhook
type webhookTestPayload struct {
	Message string `json:"message"`
}

// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Security: Validate host to prevent SSRF attacks against internal networks
	host := parsedURL.Hostname()
	if host == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must have a valid host",
		})
	}

	// Block private and reserved IP addresses to prevent SSRF
	if isPrivateIP(host) {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must not point to internal/private networks",
		})
	}

	// Block localhost and loopback addresses
	if host == "localhost" || host == "127.0.0.1" || host == "::1" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must not point to localhost",
		})
	}

	// Create a custom HTTP client with timeout and disable redirect following
	client := &http.Client{
		Timeout: 3 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Security: Limit redirects to prevent SSRF via redirect chains
			if len(via) >= 3 {
				return fmt.Errorf("too many redirects")
			}
			// Validate redirect target
			redirectURL := req.URL
			if redirectURL.Scheme != "http" && redirectURL.Scheme != "https" {
				return fmt.Errorf("redirect to invalid scheme: %s", redirectURL.Scheme)
			}
			redirectHost := redirectURL.Hostname()
			if isPrivateIP(redirectHost) || redirectHost == "localhost" || redirectHost == "127.0.0.1" || redirectHost == "::1" {
				return fmt.Errorf("redirect to blocked host: %s", redirectHost)
			}
			return nil
		},
	}

	// Prepare test payload
	testPayload := webhookTestPayload{
		Message: "Webhook configuration test",
	}
	jsonPayload, err := json.Marshal(testPayload)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to create test payload",
		})
	}

	// Send test request to webhook URL using POST method with JSON payload
	resp, err := client.Post(req.WebhookURL, "application/json", bytes.NewBuffer(jsonPayload))
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to send test request to webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the webhook responded successfully (2xx status)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Save the configuration
	// db.SaveWebhookURL(req.WebhookURL) // Assume db is a predefined database instance

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// isPrivateIP checks if a hostname resolves to a private or reserved IP address
func isPrivateIP(host string) bool {
	// Resolve hostname to IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		// If we can't resolve, assume it's not private (will fail later)
		return false
	}

	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {
			return true
		}
		// Check for IPv4 private ranges explicitly
		if ipv4 := ip.To4(); ipv4 != nil {
			switch {
			case ipv4[0] == 10:
				return true
			case ipv4[0] == 172 && ipv4[1] >= 16 && ipv4[1] <= 31:
				return true
			case ipv4[0] == 192 && ipv4[1] == 168:
				return true
			case ipv4[0] == 169 && ipv4[1] == 254:
				return true
			case ipv4[0] == 127:
				return true
			case ipv4[0] == 0:
				return true
			}
		}
	}
	return false
}

