		return fmt.Errorf("invalid URL: %v", err)
	}

	// Check for allowed protocols
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return fmt.Errorf("protocol %s is not allowed", parsedURL.Scheme)
	}

	// Resolve the hostname to IP addresses
	host := parsedURL.Hostname()

	// Check if host is an IP address
	ip := net.ParseIP(host)
	if ip != nil {
		if isPrivateIP(ip) {
			return fmt.Errorf("access to private IP addresses is not allowed")
		}
		return nil
	}

	// Resolve DNS and check all IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("failed to resolve hostname: %v", err)
	}

	for _, resolvedIP := range ips {
		if isPrivateIP(resolvedIP) {
			return fmt.Errorf("hostname resolves to a private IP address: %s", resolvedIP.String())
		}
	}

	return nil
}

// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var config WebhookConfig

	// Parse the JSON request body
	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON body: " + err.Error(),
		})
	}

	// Validate that webhook_url is provided
	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate the URL for security
	if err := validateURL(config.WebhookURL); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("URL validation failed: %v", err),
		})
	}

	// Create HTTP client with 3-second timeout and custom dialer
	client := &http.Client{
		Timeout: 3 * time.Second,
		Transport: &http.Transport{
			DialContext: (&net.Dialer{
				Timeout:   3 * time.Second,
				KeepAlive: 0,
			}).DialContext,
			DisableKeepAlives: true,
		},
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Block redirects to private IPs
			if len(via) >= 10 {
				return fmt.Errorf("too many redirects")
			}

			redirectURL := req.URL.String()
			if err := validateURL(redirectURL); err != nil {
				return fmt.Errorf("redirect blocked: %v", err)
			}
			return nil
		},
	}

	// Send a GET test request to the webhook URL
	resp, err := client.Get(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to reach webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status code: %d", resp.StatusCode),
		})
	}

	// Save the configuration
	webhookStore = config.WebhookURL

	// Return success response
	return ctx.JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// main function to set up the Fiber app and start the server
func main() {
	app := fiber.New()

	// Register the ConfigureWebhook handler for POST /configure-webhook
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the server on port 8080
	app.Listen(":8080")
}

