	}
	jsonPayload, err := json.Marshal(testPayload)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to create test payload",
		})
	}

	// Send test request to webhook URL using the validated IP for DNS rebinding protection
	resp, err := sendRequestWithValidatedIP(client, req.WebhookURL, validatedIP, jsonPayload)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Failed to send test request to webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the webhook responded successfully (2xx status)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   fmt.Sprintf("Webhook URL returned non-success status: %d", resp.StatusCode),
		})
	}

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
	})
}

// sendRequestWithValidatedIP sends a request using the validated IP to prevent DNS rebinding
func sendRequestWithValidatedIP(client *http.Client, rawURL string, validatedIP net.IP, jsonPayload []byte) (*http.Response, error) {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return nil, err
	}

	// Replace hostname with validated IP for the actual connection
	originalHost := parsedURL.Host
	if validatedIP != nil {
		parsedURL.Host = validatedIP.String()
		if parsedURL.Port() == "" {
			if parsedURL.Scheme == "https" {
				parsedURL.Host = net.JoinHostPort(parsedURL.Host, "443")
			} else {
				parsedURL.Host = net.JoinHostPort(parsedURL.Host, "80")
			}
		}
	}

	req, err := http.NewRequest("POST", parsedURL.String(), bytes.NewBuffer(jsonPayload))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")

	// Set the original Host header to ensure proper virtual host routing
	req.Host = originalHost

	return client.Do(req)
}

// isPrivateIP checks if the given hostname resolves to a private IP address
func isPrivateIP(hostname string) bool {
	// Check if hostname is an IP address directly
	ip := net.ParseIP(hostname)
	if ip != nil {
		return ip.IsPrivate() || ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast()
	}

	ips, err := net.LookupIP(hostname)
	if err != nil {
		return false
	}
	for _, ip := range ips {
		if ip.IsPrivate() || ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
			return true
		}
	}
	return false
}

// isLocalhost checks if the hostname is localhost
func isLocalhost(hostname string) bool {
	// Remove port if present
	if idx := strings.LastIndex(hostname, ":"); idx != -1 {
		hostname = hostname[:idx]
	}
	return hostname == "localhost" || hostname == "127.0.0.1" || hostname == "::1" || hostname == "0.0.0.0"
}

