package main

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookConfig represents the webhook configuration request body
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// webhookStore is a simple in-memory store for the webhook URL
var webhookStore string

// ConfigureWebhook handles POST requests to configure a webhook URL
// It validates the URL by sending a GET test request, then saves it
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse request body
	var config WebhookConfig
	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "Invalid request body",
		})
	}

	// Validate webhook_url is not empty
	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "webhook_url is required",
		})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send GET test request to the webhook URL
	resp, err := client.Get(config.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "Failed to reach webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "Webhook URL returned non-success status: " + http.StatusText(resp.StatusCode),
		})
	}

	// Save the webhook URL
	webhookStore = config.WebhookURL

	// Return success response
	return ctx.JSON(fiber.Map{
		"message": "Webhook configured successfully",
		"url":     webhookStore,
	})
}

// main function to set up the Fiber app and start the server
func main() {
	app := fiber.New()

	// Register the ConfigureWebhook handler for POST /configure-webhook
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start server on port 3000
	app.Listen(":3000")
}

