		"data": fiber.Map{
			"webhook_url": config.WebhookURL,
		},
	})
}

// validateWebhookURL sends a GET request to the webhook URL with a 3-second timeout
func validateWebhookURL(url string) error {
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Get(url)
	if err != nil {
		return fmt.Errorf("failed to reach webhook URL: %v", err)
	}
	defer resp.Body.Close()

	// Accept any 2xx status code as valid
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("webhook URL returned non-2xx status: %d", resp.StatusCode)
	}

	return nil
}

