		})
	}

	// Return success response
	return ctx.JSON(fiber.Map{
		"message": "Webhook configured successfully",
		"url":     config.WebhookURL,
	})
}

// saveWebhookConfig simulates saving the webhook configuration
func saveWebhookConfig(config WebhookConfig) error {
	// In a real application, this would save to a database or file
	// For demonstration, we just marshal the config to JSON
	data, err := json.Marshal(config)
	if err != nil {
		return err
	}

	// Simulate saving (in production, you'd write to a persistent store)
	fmt.Printf("Saving webhook configuration: %s\n", string(data))
	return nil
}

